// ─────────────────────────────────────────────────────────────────────
// Process the Discord API response and recover the original user data.
//
// Why: the HTTP Request node replaces $json with the HTTP response
// (statusCode, body, headers), so user_id and row_number are gone.
// n8n tracks which loop item produced this response via pairedItem;
// $('🔁 Loop (1 user at a time)').item walks that chain back to recover
// the original user data without needing a Merge node.
// ─────────────────────────────────────────────────────────────────────

const statusCode   = $json.statusCode;
const responseBody = String($json.body ?? '');

// Recover original user data via n8n's pairedItem chain
const loopItem  = $('🔁 Loop (1 user at a time)').item.json;
const userId    = loopItem.user_id;
const rowNumber = loopItem.row_number;

const timestamp = new Date().toISOString();
let status, errorMsg;

if (statusCode === 204 || statusCode === 200) {
  // 204 No Content = role successfully assigned
  status   = 'done';
  errorMsg = '';

} else if (statusCode === 404) {
  // User is no longer in the server — safe to skip forever
  status   = 'not_in_server';
  errorMsg = 'User not found in server — they may have left (404)';

} else if (statusCode === 429) {
  // Rate limited — leave status blank-equivalent so next run retries
  status   = 'rate_limited';
  errorMsg = `Discord rate limited the request (429): ${responseBody.substring(0, 100)}`;

} else if (statusCode === 403) {
  status   = 'failed';
  errorMsg = 'Bot lacks MANAGE_ROLES or the target role sits above the bot in the role hierarchy (403)';

} else if (statusCode == null) {
  // Network-level failure — neverError:true should prevent this, but belt-and-braces
  status   = 'failed';
  errorMsg = `Network error: ${String($json.error ?? 'unknown')}`;

} else {
  status   = 'failed';
  errorMsg = `HTTP ${statusCode}: ${responseBody.substring(0, 200)}`;
}

return [{
  json: {
    user_id:    userId,
    row_number: rowNumber,
    status,
    timestamp,
    error:      errorMsg
  }
}];
